mapper.select:
SELECT INTERVIEW_URL
FROM APPLICANT_RECORD
WHERE APPLICANT_RECORD_NO = #{applicantRecordNo}

mapper.insert:

    SELECT
        'APRC'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(APPLICANT_RECORD_NO), LENGTH('APRC' ) + 1)), 0) + 1, 6, '0')
    FROM APPLICANT_RECORD

	INSERT INTO APPLICANT_RECORD (
		APPLICANT_RECORD_NO
		, RECRUIT_PROCESS_NO
		, APPLICANT_ID
		, APPLICANT_NAME
		, STEP_PASS_YN
		, STEP_APPLICATION_YN
	) VALUES (
		#{applicantRecordNo}
		, #{recruitProcessNo}
		, #{applicantId}
		, #{applicantName}
		, 'N'
		, 'N'
	)

mapper.update:
UPDATE APPLICANT_RECORD 
SET 
	INTERVIEW_URL = #{interviewUrl}
	, EVALUATION_START_TIME = TO_TIMESTAMP(#{evaluationStartTime}, 'YYYY-MM-DD"T"HH24:MI')
WHERE APPLICANT_RECORD_NO =	#{applicantRecordNo}

UPDATE APPLICANT_RECORD 
SET 
	STEP_APPLICATION_YN = 'Y'
WHERE RECRUIT_PROCESS_NO = #{processNo}
AND APPLICANT_ID = #{applicantId}

UPDATE APPLICANT_RECORD SET 
	RECRUIT_PROCESS_STEP = #{recruitProcessStep}
	, STEP_PASS_YN = #{stepPassYn}
	, STEP_APPLICATION_YN = #{stepApplicationYn} 
WHERE APPLICANT_RECORD_NO =	#{applicantRecordNo}

UPDATE APPLICANT_RECORD SET
	STEP_PASS_YN = 'Y'
WHERE APPLICANT_ID = #{applicantId}
AND RECRUIT_PROCESS_NO = #{recruitProcessNo}

UPDATE APPLICANT_RECORD SET
	FAILED_YN = 'Y'
WHERE APPLICANT_ID = #{applicantId}
AND RECRUIT_PROCESS_NO = #{recruitProcessNo}
